const assert = require('node:assert/strict');

const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const rows = [
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'c', tenant: 'a', createdAt: '2026-01-02', total: 5 },
  { id: 'z', tenant: 'b', createdAt: '2026-01-02', total: 9 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'd', tenant: 'a', createdAt: '2026-01-03', total: 4 }
];

const handler = new OrderHandler(new OrderRepository(rows));

// First page for a tenant: tenant filter, ascending createdAt then id.
let page = handler.list({ tenant: 'a', limit: 2 });
assert.deepEqual(page.items.map(o => o.id), ['a', 'b']);
assert.equal(page.nextCursor, '2026-01-02|b');

// Resume strictly after the pair; equal dates continue by id.
page = handler.list({ tenant: 'a', limit: 1, cursor: '2026-01-02|b' });
assert.deepEqual(page.items.map(o => o.id), ['c']);
assert.equal(page.nextCursor, '2026-01-02|c');

// Page of exactly the limit with no further matching order: null cursor.
page = handler.list({ tenant: 'a', limit: 2, cursor: '2026-01-02|b' });
assert.deepEqual(page.items.map(o => o.id), ['c', 'd']);
assert.equal(page.nextCursor, null);

// Cursor with no rows after it: empty page, null cursor.
page = handler.list({ tenant: 'a', limit: 2, cursor: '2026-01-03|d' });
assert.deepEqual(page.items.map(o => o.id), []);
assert.equal(page.nextCursor, null);

// Page shorter than the limit is the last page.
page = handler.list({ tenant: 'a', limit: 10 });
assert.deepEqual(page.items.map(o => o.id), ['a', 'b', 'c', 'd']);
assert.equal(page.nextCursor, null);

// A cursor that no row matches (future date) resumes cleanly.
page = handler.list({ tenant: 'a', limit: 5, cursor: '2026-05-01|a' });
assert.deepEqual(page.items.map(o => o.id), []);
assert.equal(page.nextCursor, null);

// Full walk never repeats or skips equal-date orders.
const walked = [];
let cursor;
do {
  const p = handler.list({ tenant: 'a', limit: 2, cursor });
  walked.push(...p.items.map(o => o.id));
  cursor = p.nextCursor;
} while (cursor);
assert.deepEqual(walked, ['a', 'b', 'c', 'd']);

// All ids equal-date: tie broken by id across page boundaries.
const sameDate = new OrderHandler(new OrderRepository(
  ['e', 'd', 'c', 'b', 'a'].map(id => ({ id, tenant: 't', createdAt: '2026-01-01', total: 1 }))
));
page = sameDate.list({ tenant: 't', limit: 5 });
assert.deepEqual(page.items.map(o => o.id), ['a', 'b', 'c', 'd', 'e']);
assert.equal(page.nextCursor, null);
page = sameDate.list({ tenant: 't', limit: 2 });
assert.deepEqual(page.items.map(o => o.id), ['a', 'b']);
assert.equal(page.nextCursor, '2026-01-01|b');
page = sameDate.list({ tenant: 't', limit: 2, cursor: '2026-01-01|b' });
assert.deepEqual(page.items.map(o => o.id), ['c', 'd']);
assert.equal(page.nextCursor, '2026-01-01|d');
page = sameDate.list({ tenant: 't', limit: 2, cursor: '2026-01-01|d' });
assert.deepEqual(page.items.map(o => o.id), ['e']);
assert.equal(page.nextCursor, null);

// Cursor resumes even when its row has since been deleted.
const withGone = [
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'gone', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'next', tenant: 'a', createdAt: '2026-01-02', total: 3 }
];
page = new OrderHandler(new OrderRepository(withGone)).list({ tenant: 'a', limit: 1 });
assert.deepEqual(page.items.map(o => o.id), ['a']);
assert.equal(page.nextCursor, '2026-01-01|a');
const afterDeletion = [
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'next', tenant: 'a', createdAt: '2026-01-02', total: 3 }
];
page = new OrderHandler(new OrderRepository(afterDeletion)).list({ tenant: 'a', limit: 5, cursor: '2026-01-01|a' });
assert.deepEqual(page.items.map(o => o.id), ['next']);
assert.equal(page.nextCursor, null);

// Filtering precedes pagination, even for a cursor pair from another tenant.
const mixed = new OrderHandler(new OrderRepository([
  { id: 'early', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'foreign', tenant: 'b', createdAt: '2026-01-02', total: 2 },
  { id: 'foreign2', tenant: 'b', createdAt: '2026-01-03', total: 5 },
  { id: 'late', tenant: 'a', createdAt: '2026-01-04', total: 3 }
]));
page = mixed.list({ tenant: 'b', limit: 1 });
assert.deepEqual(page.items.map(o => o.id), ['foreign']);
assert.equal(page.nextCursor, '2026-01-02|foreign');
page = mixed.list({ tenant: 'a', limit: 5, cursor: '2026-01-02|foreign' });
assert.deepEqual(page.items.map(o => o.id), ['late']);
assert.equal(page.nextCursor, null);

// Invalid requests.
assert.throws(() => handler.list({ tenant: '', limit: 1 }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 0 }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 101 }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1.5 }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: NaN }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: '' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: 'a' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: 'a|' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: '|b' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: 'a|b|c' }), /invalid request/);
assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor: '||' }), /invalid request/);

// The repository never mutates its input array or rows.
const pristine = [
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'z', tenant: 'b', createdAt: '2026-01-01', total: 9 }
];
const snapshot = JSON.parse(JSON.stringify(pristine));
new OrderHandler(new OrderRepository(pristine)).list({ tenant: 'a', limit: 1, cursor: '2026-01-01|a' });
assert.deepEqual(pristine, snapshot);
assert.deepEqual(pristine.map(o => o.id), ['b', 'a', 'z']); // original order kept

// Response shape.
assert.deepEqual(Object.keys(handler.list({ tenant: 'a', limit: 1 })).sort(), ['items', 'nextCursor']);
const single = handler.list({ tenant: 'a', limit: 1 });
assert.equal(typeof single.nextCursor, 'string');
assert.equal(single.nextCursor, '2026-01-01|a');

console.log('checks/cursor.cjs passed');
EOF

