import { CursorPair, Order } from './types';

// Ascending lexicographic (createdAt, id) order, shared by page sorting and
// cursor resume comparisons.
function compareByCreatedAtThenId(a: CursorPair, b: CursorPair): number {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  // Rows of `tenant` in ascending (createdAt, id) order. With `after`, only
  // rows strictly after that pair are returned, so a cursor resumes by pair
  // comparison even if its row was deleted, and equal-date orders are neither
  // repeated nor skipped. The tenant filter always runs before pagination,
  // and neither the input array nor its rows are mutated: sorting operates on
  // the fresh filtered copy.
  list(tenant: string, after?: CursorPair): Order[] {
    const tenantRows = this.rows.filter(row => row.tenant === tenant);
    tenantRows.sort(compareByCreatedAtThenId);
    return after ? tenantRows.filter(row => compareByCreatedAtThenId(row, after) > 0) : tenantRows;
  }
}
EOF

